/** @odoo-module **/

/**
 * Robust, lightweight GitHub Flavored Markdown (GFM) parser for GSUS AI.
 * Converts markdown text into responsive, sanitized HTML elements.
 */
export function markdownToHtml(md, previewMap = null) {
    if (!md || typeof md !== "string") {
        return "";
    }

    let text = md.trim().replace(/\r\n/g, "\n").replace(/\r/g, "\n");

    // Clean stray placeholder tokens generated by some open-source models
    text = text.replace(/\bINLINECODE\d+\b/gi, "").replace(/\bCODEBLOCK\d+\b/gi, "");

    // 1. Code blocks (fenced ```...```)
    const codeBlocks = [];
    text = text.replace(/```(\w*)\n([\s\S]*?)```/g, (match, lang, code) => {
        const id = `§§CODEBLOCK${codeBlocks.length}§§`;
        const escapedCode = escapeHtml(code.trim());
        const langBadge = lang ? `<span class="o_gsus_ai_code_lang">${escapeHtml(lang)}</span>` : "";
        codeBlocks.push(
            `<div class="o_gsus_ai_code_container my-2">` +
                `<div class="o_gsus_ai_code_header d-flex justify-content-between align-items-center">` +
                    `${langBadge}` +
                    `<button class="btn btn-xs btn-outline-light o_gsus_ai_copy_code_btn" onclick="navigator.clipboard.writeText(this.closest('.o_gsus_ai_code_container').querySelector('code').innerText); this.innerText='Copied!'; setTimeout(()=>this.innerText='Copy', 1500);">Copy</button>` +
                `</div>` +
                `<pre class="o_gsus_ai_pre mb-0"><code>${escapedCode}</code></pre>` +
            `</div>`
        );
        return id;
    });

    // 2. Inline code (`code`)
    const inlineCodes = [];
    text = text.replace(/`([^`\n]+)`/g, (match, code) => {
        const id = `§§INLINECODE${inlineCodes.length}§§`;
        inlineCodes.push(`<code class="o_gsus_ai_inline_code">${escapeHtml(code)}</code>`);
        return id;
    });

    // 3. Robust Line-by-Line GFM Markdown Table Parser
    const lines = text.split("\n");
    const outputLines = [];
    let i = 0;
    while (i < lines.length) {
        const rawLine = lines[i];
        const trimmed = rawLine.trim();
        const nextTrimmed = (i + 1 < lines.length) ? lines[i + 1].trim() : "";

        // Detect a table if current line has pipes and next line is a separator like |---|---|
        const isTableRow = (str) => str.startsWith("|") && str.endsWith("|") && str.includes("|");
        const isSeparator = (str) => isTableRow(str) && /^\|[\s\-:|]+\|$/.test(str);

        if (isTableRow(trimmed) && isSeparator(nextTrimmed)) {
            const tableRows = [trimmed];
            i += 2; // advance past header and delimiter line
            while (i < lines.length && isTableRow(lines[i].trim())) {
                tableRows.push(lines[i].trim());
                i++;
            }

            const parseRow = (row) => {
                // Slice outer pipes and split by remaining |
                const inner = row.slice(1, -1);
                return inner.split("|").map((cell) => cell.trim());
            };

            const headers = parseRow(tableRows[0]);
            let tableHtml = `<div class="table-responsive my-3"><table class="table table-sm table-bordered table-hover o_gsus_ai_table">`;
            tableHtml += `<thead><tr>`;
            for (const h of headers) {
                tableHtml += `<th>${parseInline(h, previewMap)}</th>`;
            }
            tableHtml += `</tr></thead><tbody>`;

            for (let r = 1; r < tableRows.length; r++) {
                const cols = parseRow(tableRows[r]);
                tableHtml += `<tr>`;
                for (let c = 0; c < headers.length; c++) {
                    const cellContent = cols[c] !== undefined ? cols[c] : "";
                    tableHtml += `<td>${parseInline(cellContent, previewMap)}</td>`;
                }
                tableHtml += `</tr>`;
            }
            tableHtml += `</tbody></table></div>`;
            outputLines.push(tableHtml);
        } else {
            outputLines.push(rawLine);
            i++;
        }
    }
    text = outputLines.join("\n");

    // 4. Headings
    text = text.replace(/^#### (.*?)$/gm, '<h6 class="o_gsus_ai_heading o_gsus_ai_h6 mt-3 mb-1">$1</h6>');
    text = text.replace(/^### (.*?)$/gm, '<h5 class="o_gsus_ai_heading o_gsus_ai_h5 mt-3 mb-2">$1</h5>');
    text = text.replace(/^## (.*?)$/gm, '<h4 class="o_gsus_ai_heading o_gsus_ai_h4 mt-3 mb-2">$1</h4>');
    text = text.replace(/^# (.*?)$/gm, '<h3 class="o_gsus_ai_heading o_gsus_ai_h3 mt-3 mb-2">$1</h3>');

    // 5. Blockquotes (> ...)
    text = text.replace(/^> (.*?)$/gm, '<blockquote class="o_gsus_ai_blockquote ps-3 border-start border-3 border-primary my-2 text-muted">$1</blockquote>');

    // 6. Horizontal Rules
    text = text.replace(/^(?:---|\*\*\*|___)$/gm, '<hr class="o_gsus_ai_hr my-3"/>');

    // 7. Bullet Lists (- or * or +)
    text = text.replace(/(?:^|\n)((?:[\*\-\+] .*(?:\n|$))+)/g, (match, listContent) => {
        const items = listContent.trim().split("\n").map((item) => {
            const clean = item.replace(/^[\*\-\+]\s+/, "");
            return `<li>${parseInline(clean, previewMap)}</li>`;
        });
        return `<ul class="o_gsus_ai_list my-2">${items.join("")}</ul>`;
    });

    // 8. Numbered Lists (1. 2. 3.)
    text = text.replace(/(?:^|\n)((?:\d+\. .*(?:\n|$))+)/g, (match, listContent) => {
        const items = listContent.trim().split("\n").map((item) => {
            const clean = item.replace(/^\d+\.\s+/, "");
            return `<li>${parseInline(clean, previewMap)}</li>`;
        });
        return `<ol class="o_gsus_ai_olist my-2">${items.join("")}</ol>`;
    });

    // 9. Paragraphs and line breaks
    const paragraphs = text.split(/\n{2,}/);
    text = paragraphs
        .map((p) => {
            p = p.trim();
            // Don't wrap if already starting with block tag
            if (/^<(div|table|h\d|ul|ol|blockquote|hr)/i.test(p)) {
                return p;
            }
            return `<p class="o_gsus_ai_p mb-2">${parseInline(p.replace(/\n/g, "<br/>"), previewMap)}</p>`;
        })
        .join("\n");

    // 10. Restore code blocks and inline code
    inlineCodes.forEach((html, i) => {
        text = text.replaceAll(`§§INLINECODE${i}§§`, html);
    });
    codeBlocks.forEach((html, i) => {
        text = text.replaceAll(`§§CODEBLOCK${i}§§`, html);
    });

    return text;
}

function parseInline(text, previewMap = null) {
    if (!text) return "";
    let s = text;
    // Bold (**text** or __text__)
    s = s.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/__([^_]+)__/g, "<strong>$1</strong>");
    // Italic (*text* or _text_)
    s = s.replace(/\*(.*?)\*/g, "<em>$1</em>");
    // Only match underscore italics at word/space boundary, not inside identifiers like uom_id or purchase_ok
    s = s.replace(/(?:^|\s)_([^_]+)_(?=\s|$|[.,!?;:])/g, (m, p1) => ` <em>${p1}</em>`);
    // Strikethrough (~~text~~)
    s = s.replace(/~~(.*?)~~/g, "<del>$1</del>");
    // Images (![alt](url)) -> Render Rich GSUS AI Media Card
    s = s.replace(/!\[(.*?)\]\((.*?)\)/g, (match, alt, url) => {
        let name = alt || "Attached Image";
        let sizeText = "";
        if (name.includes("|")) {
            const parts = name.split("|");
            name = parts[0].trim();
            sizeText = parts[1].trim();
        }
        let effectiveUrl = url;
        if (previewMap && previewMap.get && previewMap.get(name)) {
            effectiveUrl = previewMap.get(name);
        }
        return `<div class="o_gsus_ai_media_card my-2" data-media-url="${escapeHtml(effectiveUrl)}" data-media-name="${escapeHtml(name)}"><div class="o_gsus_ai_media_preview_container"><img src="${escapeHtml(effectiveUrl)}" alt="${escapeHtml(name)}" class="o_gsus_ai_media_img" loading="lazy" onerror="this.closest('.o_gsus_ai_media_card').classList.add('is-error');"/><div class="o_gsus_ai_media_overlay"><span class="o_gsus_ai_media_inspect_pill"><i class="oi me-1" data-icon="search"></i> Inspect</span></div></div><div class="o_gsus_ai_media_info"><div class="o_gsus_ai_media_name" title="${escapeHtml(name)}"><i class="oi me-1" data-icon="image"></i> ${escapeHtml(name)}</div>${sizeText ? `<span class="o_gsus_ai_media_size">${escapeHtml(sizeText)}</span>` : ""}</div></div>`;
    });
    // Links ([text](url))
    s = s.replace(/\[(.*?)\]\((.*?)\)/g, (match, label, url) => {
        if (url && url.startsWith("odoo-action://")) {
            const actionXmlId = url.replace("odoo-action://", "");
            return `<a href="javascript:void(0)" data-odoo-action="${escapeHtml(actionXmlId)}" class="o_gsus_ai_action_link text-primary fw-semibold"><i class="oi me-1" data-icon="settings"></i>${label}</a>`;
        }
        if (url && url.startsWith("odoo://")) {
            const parts = url.replace("odoo://", "").split("/");
            const model = parts[0] || "";
            const id = parts[1] || "";
            return `<a href="javascript:void(0)" data-odoo-model="${escapeHtml(model)}" data-odoo-id="${escapeHtml(id)}" class="o_gsus_ai_record_link text-primary fw-semibold"><i class="oi me-1" data-icon="open_in_new"></i>${label}</a>`;
        }
        return `<a href="${url}" target="_blank" rel="noopener noreferrer" class="o_gsus_ai_link text-primary">${label}</a>`;
    });
    return s;
}

function escapeHtml(str) {
    return str
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}
